SER=$(/opt/homebrew/bin/adb devices | awk '$2=="device"{print $1}' | head -1); a(){ /opt/homebrew/bin/adb -s "$SER" "$@"; }; slp(){ python3 -I -c "import time,sys;time.sleep(float(sys.argv[1]))" "$1"; }; P=org.opemamalur.scene
grab(){ a exec-out screencap -p > "$S/ui/t/$1.png"; W=$(sips -g pixelWidth "$S/ui/t/$1.png" | tail -1 | awk '{print $2}'); if [ "$W" = 1680 ]; then python3 -I "$S/scripts/pngcrop.py" "$S/ui/t/$1.png" "$S/ui/t/$1-s.png" 1680 1120 840; else sips -Z 840 "$S/ui/t/$1.png" --out "$S/ui/t/$1-s.png" >/dev/null 2>&1; fi; }
FULL(){ a exec-out screencap -p > "$S/ui/t/p.png"; W=$(sips -g pixelWidth "$S/ui/t/p.png" | tail -1 | awk '{print $2}'); [ "$W" = 1680 ] && echo 150 || echo 100; }
go(){ a shell input keyevent KEYCODE_WAKEUP; a shell wm dismiss-keyguard; a shell setprop debug.opem.world town; a shell setprop debug.opem.profile $1; a shell setprop debug.opem.live $2; a shell setprop debug.opem.shadow $3; a shell setprop debug.opem.crowd $4; a shell setprop debug.opem.fx $5; a shell setprop debug.opem.far $6; a shell setprop debug.opem.tour $7; a shell setprop debug.opem.tourr 600; a shell setprop debug.opem.walk 0; a shell setprop debug.opem.scale $SCALE; a logcat -c; a shell am force-stop $P; a shell monkey -p $P -c android.intent.category.LAUNCHER 1 >/dev/null 2>&1; }
L(){ a logcat -d -s OpemAmalurScene | grep -E 'PROFILE interval|STREAM cells' | tail -2 | sed -E 's/^.*OpemAmalurScene: //;s/PROFILE //;s/gpu_samples=[0-9]+//' | cut -c1-140; }
mem(){ a shell dumpsys meminfo $P 2>/dev/null | grep -E 'TOTAL PSS' | tr -s ' ' | cut -c1-24; }
